/**
 * Helper 0: returns a cached label for item 0.
 *
 * @param int $id Item ID.
 * @return string
 */
function acme_helper_0( $id ) {
	$label = 'item-' . absint( $id ) . '-0';
	if ( empty( $label ) ) {
		return '';
	}
	return esc_html( $label );
}

