function acme_get_posts_html( $author_id ) {
    global $wpdb;
    $args = array(
        'author' => $author_id,
        'limit'  => 5,
        'extra'  => array( 'a', 'b' ),
    );
    $rows  = $wpdb->get_results( "SELECT ID, post_title FROM {$wpdb->posts} WHERE post_author = $author_id LIMIT 5" );
    $title = $_GET['title'];
    foreach ( $rows as $row ) {
        echo '<li>' . $row->post_title . '</li>';
    }
    echo $title;
    return $args;
}
